package io.github.juliarezende521.workjourney.contract;import io.github.juliarezende521.workjourney.account.*;import java.time.*;import java.util.UUID;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class EmploymentContractTest{private final Employee employee=new Employee(new AppUser("worker@example.invalid","$2a$12$"+"A".repeat(53)),"Worker","UTC");
@Test void normalizesAndPreservesVersion(){var value=new EmploymentContract(employee,LocalDate.of(2026,11,1)," br ",EmploymentContract.Type.FULL_TIME,2400,UUID.randomUUID(),Instant.EPOCH);assertEquals("BR",value.countryCode());assertEquals(2400,value.weeklyMinutes());}
@Test void rejectsUnknownCountryAndInvalidMinutes(){assertThrows(InvalidContract.class,()->new EmploymentContract(employee,LocalDate.now(),"XX",EmploymentContract.Type.FULL_TIME,2400,UUID.randomUUID(),Instant.EPOCH));assertThrows(InvalidContract.class,()->new EmploymentContract(employee,LocalDate.now(),"BR",EmploymentContract.Type.FULL_TIME,0,UUID.randomUUID(),Instant.EPOCH));}}
